/**
 * Source a server sent event.
 *
 * Multiple sources may share the same underlying connection if they use the same path (`from`) and the same options (`options`).
 * > ## Example
 * > ```js
 * > const connection = source({
 * >  from: '/events',
 * >  options: {
 * >    headers: {
 * >      'Authorization': `Bearer ${token}`
 * >    }
 * >  }
 * > })
 * > ```
 * @param {string} from Path to the stream.
 * @param {import('./types.external').SourceConfiguration} [configuration]
 * @returns {import('./types.external').Source}
 */
export function source(from: string, { error, close, open, cache, options }?: import("./types.external").SourceConfiguration): import("./types.external").Source;
